using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;using Unity.AI.Navigation;using FireSafety;
public static class FurnishSchool {
const string R="Assets/_FireSafety/SchoolExpansion/",S="Assets/ThirdParty/SchoolExpansion/";
static Dictionary<string,Material> mats=new Dictionary<string,Material>();
static Material Mat(string key,Color color){if(mats.ContainsKey(key))return mats[key];var m=AssetDatabase.LoadAssetAtPath<Material>(R+"Materials/"+key+".mat");if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=key};AssetDatabase.CreateAsset(m,R+"Materials/"+key+".mat");}m.color=color;m.SetFloat("_Smoothness",.22f);m.enableInstancing=true;mats[key]=m;return m;}
static Bounds BoundsOf(GameObject g){var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
static void Convert(GameObject g,string prefix){foreach(var r in g.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>Mat(prefix+"_"+m.name,m.HasProperty("_Color")?m.color:Color.gray)).ToArray();}}
static GameObject Model(string path,Transform parent,string name,float size,bool height=true){var wrapper=new GameObject(name);wrapper.transform.SetParent(parent,false);var visual=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path),wrapper.transform);visual.name="Model";var b=BoundsOf(visual);visual.transform.localScale*=size/(height?b.size.y:b.size.x);b=BoundsOf(visual);visual.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z)-wrapper.transform.position;return wrapper;}
static Material PlantMaterial(Material source,string asset){string n=source.name;var m=Mat(n+"_URP",Color.white);var files=Directory.GetFiles(S+asset+"/textures");string diff=files.FirstOrDefault(f=>f.Contains(n+"_basecolor_alpha")&&!f.EndsWith(".meta"))??files.First(f=>f.Contains(n+"_diff_")&&!f.EndsWith(".meta"));m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(diff.Replace('\\','/')));string norm=files.FirstOrDefault(f=>f.Contains(n+"_nor_gl_")&&!f.EndsWith(".meta"));if(norm!=null){m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(norm.Replace('\\','/')));m.EnableKeyword("_NORMALMAP");}m.SetFloat("_Cull",0);m.doubleSidedGI=true;m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.45f);m.EnableKeyword("_ALPHATEST_ON");m.renderQueue=2450;return m;}
static GameObject Plant(string asset,string part,float height){var root=new GameObject(asset+"_garden");var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(S+asset+"/"+asset+".fbx"),root.transform);if(part!=null)foreach(var r in model.GetComponentsInChildren<Renderer>())if(!r.name.Contains(part))UnityEngine.Object.DestroyImmediate(r.gameObject);
foreach(var r in model.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>PlantMaterial(m,asset)).ToArray();r.shadowCastingMode=asset.Contains("grass")?ShadowCastingMode.Off:ShadowCastingMode.On;}
var b=BoundsOf(root);model.transform.localScale*=height/b.size.y;b=BoundsOf(root);model.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);
var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(asset.Contains("grass")?.015f:.008f,root.GetComponentsInChildren<Renderer>())});lod.RecalculateBounds();var prefab=PrefabUtility.SaveAsPrefabAsset(root,R+"Prefabs/"+root.name+".prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
static void Box(string name,Transform parent,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.position=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;}
public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(GameObject.Find("School occupants"))throw new Exception("Occupants exist");AssetDatabase.Refresh();var root=GameObject.Find("School expansion").transform;
var garden=new GameObject("Courtyard landscaping").transform;garden.SetParent(root,false);var tree=Plant("quiver_tree_01",null,4.4f);var shrub=Plant("shrub_01","_f_",.8f);var grass=Plant("grass_bermuda_01","_medium_a",.13f);
var soil=Mat("Garden soil",new Color(.12f,.16f,.07f));var paving=UnityEngine.Object.FindObjectsByType<Renderer>().SelectMany(r=>r.sharedMaterials).First(m=>m&&m.name=="Courtyard - Poly Haven concrete pavers");
int index=0;foreach(float z in new[]{-18f,-10f,10f,18f}){Box("Planted garden bed",garden,new Vector3(20,.015f,z),new Vector3(3.2f,.07f,5.4f),soil);foreach(float side in new[]{-1f,1f})Box("Garden stone edging",garden,new Vector3(20+side*1.68f,.06f,z),new Vector3(.12f,.16f,5.6f),paving);var t=(GameObject)PrefabUtility.InstantiatePrefab(tree,garden);t.transform.position=new Vector3(20,0,z);t.transform.rotation=Quaternion.Euler(0,index++*67,0);var col=t.AddComponent<CapsuleCollider>();col.center=new Vector3(0,1.8f,0);col.radius=.25f;col.height=3.6f;
for(int j=0;j<4;j++){var sh=(GameObject)PrefabUtility.InstantiatePrefab(shrub,garden);sh.transform.position=new Vector3(19.2f+(j%2)*1.6f,.06f,z+(j<2?-1.8f:1.8f));sh.transform.rotation=Quaternion.Euler(0,j*83,0);}
for(int j=0;j<24;j++){var gr=(GameObject)PrefabUtility.InstantiatePrefab(grass,garden);gr.transform.position=new Vector3(18.6f+(j%6)*.55f,.06f,z-2.4f+(j/6)*1.5f);gr.transform.rotation=Quaternion.Euler(0,j*47,0);gr.transform.localScale=Vector3.one*1.8f;}}
var computers=new GameObject("Classroom 1 - two desktop computers").transform;computers.SetParent(root,false);
var desk=GameObject.Find("Classroom - licensed source art").transform.Find("Desk");var extra=new GameObject("Second computer desk").transform;extra.SetParent(computers,false);foreach(Transform c in desk.Find("teacherDesk"))if(c.name.StartsWith("TeacherDesk")){var copy=UnityEngine.Object.Instantiate(c.gameObject,extra,true);copy.transform.position+=new Vector3(2.1f,0,-1.1f);}
for(int i=0;i<2;i++){var computer=new GameObject("Desktop computer "+(i+1)).transform;computer.SetParent(computers,false);var origin=i==0?new Vector3(-1.82f,.814f,-2.26f):new Vector3(.61f,.814f,-3.37f);var screen=Model(S+"Computers/computerScreen.fbx",computer,"Monitor",.48f,false);screen.transform.position=origin+new Vector3(0,0,-.14f);Convert(screen,"Computer");var keyboard=Model(S+"Computers/computerKeyboard.fbx",computer,"Keyboard",.31f,false);keyboard.transform.position=origin+new Vector3(0,0,.12f);Convert(keyboard,"Computer");var mouse=Model(S+"Computers/computerMouse.fbx",computer,"Mouse",.055f,false);mouse.transform.position=origin+new Vector3(.22f,0,.12f);Convert(mouse,"Computer");}
var surface=UnityEngine.Object.FindAnyObjectByType<NavMeshSurface>();surface.BuildNavMesh();EditorUtility.SetDirty(surface.navMeshData);Physics.SyncTransforms();
var crowd=new GameObject("School occupants");var controller=crowd.AddComponent<SchoolEvacuationController>();controller.session=UnityEngine.Object.FindAnyObjectByType<TrainingSession>();controller.exit=UnityEngine.Object.FindAnyObjectByType<ExitDoor>();var people=new List<SchoolEvacuee>();
var candidates=new[]{new Vector3(-1.1f,0,-3.4f),new Vector3(-2.35f,0,-1.2f),new Vector3(-1.1f,0,-1.2f),new Vector3(.15f,0,-1.2f),new Vector3(1.4f,0,-1.2f),new Vector3(.15f,0,-.1f),new Vector3(1.4f,0,-.1f),new Vector3(.15f,0,1.05f),new Vector3(-1.1f,0,2.25f),new Vector3(.15f,0,2.25f),new Vector3(-1.1f,0,3.3f)};
string[] names={"Casual_Male","Casual_Female","Casual2_Male","Casual2_Female"};for(int i=0;i<11;i++){NavMeshHit hit;if(!NavMesh.SamplePosition(candidates[i],out hit,.3f,NavMesh.AllAreas))throw new Exception("NPC spawn missing "+i);var path=new NavMeshPath();NavMesh.CalculatePath(hit.position,new Vector3(15,0,0),NavMesh.AllAreas,path);if(path.status!=NavMeshPathStatus.PathComplete)throw new Exception("NPC path disconnected "+i);
var g=new GameObject(i==0?"Teacher":"Student "+i.ToString("00"));g.transform.SetParent(crowd.transform,false);string modelPath=S+"Characters/"+(i==0?"Suit_Male":names[(i-1)%4])+".fbx";var visual=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(modelPath),g.transform);visual.name="Character visual";var clips=AssetDatabase.LoadAllAssetsAtPath(modelPath).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).ToArray();var idle=clips.First(c=>c.name.EndsWith("|Idle"));idle.SampleAnimation(visual,0);visual.transform.localScale=Vector3.one*(i==0?.54f:.49f);visual.transform.localPosition=Vector3.up*.025f;foreach(var skin in visual.GetComponentsInChildren<SkinnedMeshRenderer>())skin.updateWhenOffscreen=true;Convert(visual,i==0?"Teacher":"Student");var animation=visual.GetComponent<Animation>()??visual.AddComponent<Animation>();foreach(var clip in clips)animation.AddClip(clip,clip.name);animation.clip=idle;animation.playAutomatically=true;animation.wrapMode=WrapMode.Loop;animation.cullingType=AnimationCullingType.AlwaysAnimate;
g.transform.position=hit.position;g.transform.rotation=Quaternion.Euler(0,i==0?0:180,0);var agent=g.AddComponent<NavMeshAgent>();agent.agentTypeID=surface.agentTypeID;agent.radius=.20f;agent.height=1.65f;agent.speed=2.2f;agent.acceleration=7;agent.angularSpeed=540;agent.stoppingDistance=.12f;agent.avoidancePriority=25+i*4;agent.obstacleAvoidanceType=ObstacleAvoidanceType.MedQualityObstacleAvoidance;
var person=g.AddComponent<SchoolEvacuee>();person.initialPosition=g.transform.position;person.initialRotation=g.transform.rotation;person.assemblyPosition=new Vector3(14.5f+(i%3)*.65f,0,-1.65f+(i/3)*.85f);person.departureDelay=i*.28f;person.legacyAnimation=animation;person.idleClip=idle.name;person.walkClip=clips.First(c=>c.name.EndsWith("|Walk")).name;people.Add(person);}
controller.people=people.ToArray();EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();return new{people=people.Count,computers=computers.childCount-1,trees=4,shrubs=16,grass=96};}}



